// The randomizer's seed generation in the background (docs/RANDOMIZER_PLAN.md step R4.3, decisions
// D3, D5, D6): one job at a time runs pcr::generate (pc_rando_gen.h) on a worker thread and writes
// its files there, so the game thread never waits on the generator or on the SD card:
//   - the logs (D5) into GenJobPaths::logDir: "WW Random <seed> - Spoiler Log.txt" and
//     "- Non-Spoiler Log.txt" on success, "- Error Log.txt" on failure, each followed by the line
//     "Generated by SwitchWaker <version>"; the files of the other outcome left there by an earlier
//     run of the same seed are removed (as cos_rando_cli does);
//   - the placement as the slot's sidecar (D3) into GenJobPaths::cardDir
//     (pc_rando_slot_write_sidecar: switchwaker-rando-<hash32>.json). The next New Game finds it
//     there already; a seed never used leaves an orphan sidecar, which R4.4's clean action removes.
// The game thread starts the job, reads its progress every frame and takes the result when it is
// over (the options menu, pc_rando_menu.cpp, then makes it the pending seed).
//
// Pure C++ with no game code (cos_rando_core; unit test test_R4_3.cpp). The worker is a detached
// pthread with an 8 MiB stack (the Switch's wrapper gives at least 4 MiB); the job's state is
// shared between the two threads and outlives the program's static destructors, so quitting while
// a seed is generated is safe. GenJobThreadHooks lets the game run the worker inside its host
// allocation scope (the global operator new would otherwise take blocks of the game's current
// JKRHeap from another thread).
#pragma once

#include "pc_rando_gen.h"

#include <string>

namespace pcr {

struct GenJobPaths {
    std::string logDir;  // created (with its parents) when missing; "" writes no logs
    std::string cardDir; // created when missing; "" writes no sidecar
};

enum class GenJobState { Idle, Running, Done };

struct GenJobProgress {
    GenJobState state = GenJobState::Idle;
    std::string text; // the generator's last progress text ("" before the first)
    int done = 0;
    int total = 0;
};

struct GenJobResult {
    GenResult gen;          // the generator's result (gen.ok, gen.error, gen.seed, the logs)
    std::string version;    // the request's version (the logs' trailer)
    double seconds = 0.0;   // generation time, files excluded
    std::string spoilerPath, nonSpoilerPath, errorPath, sidecarPath; // "" when not written
    std::string fileError;  // the first file that could not be written ("" none)
};

// Called on the worker thread before the job starts and after it ended (nullptr: none).
struct GenJobThreadHooks {
    void (*enter)() = nullptr;
    void (*exit)() = nullptr;
};
void genJobSetThreadHooks(const GenJobThreadHooks& hooks);

// Starts a job. False (nothing started) when one is running or its result was not taken yet, or
// the thread could not be made (*err says which).
bool genJobStart(const GenRequest& req, const GenJobPaths& paths, std::string* err);
// The state and the last progress line. Any thread.
GenJobProgress genJobProgress();
// When the job is Done: moves its result into *out and the state back to Idle. False otherwise.
bool genJobTake(GenJobResult* out);
// Blocks until no job runs (tests, the CLI). Returns at once when none runs.
void genJobWait();

// The file writes of a job, also usable on their own: the logs and the sidecar of `res` into
// `paths` (see above). Fills the paths and fileError of *out.
void genJobWriteFiles(const GenResult& res, const std::string& version, const GenJobPaths& paths,
                      GenJobResult* out);

// mkdir -p. True when the folder exists afterwards.
bool genJobMakeDirs(const std::string& dir);

} // namespace pcr
